/* Inject custom component classes into the components layer */
@layer components {
  .btn-primary {
    @apply px-4 py-2 bg-indigo-600 text-white font-medium rounded-lg shadow-sm transition-colors hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 active:scale-95;
  }
}

